<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {ArrowLeft,ArrowRight,Check,Copy,ShieldCheck,RefreshCw} from 'lucide-vue-next'
type State={confirmed?:boolean;schedule?:{enabled:boolean;time:string};signing?:boolean;request_id?:string;csrf?:string;command?:string;expires_at?:number;qq?:string;roles?:string[];credential_source?:string;complete?:boolean;results?:{state:string;message:string}[]}
const state=ref<State>({}),busy=ref(false),error=ref(''),token=ref(''),auto=ref(true),consent=ref(false),copied=ref(false),ready=ref(false),cancelled=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const stage=computed(()=>state.value.complete?4:state.value.roles?3:state.value.confirmed?2:1)
const requestID=new URLSearchParams(location.search).get('r')||new URLSearchParams(location.hash.split('?')[1]||'').get('r')||''
async function api(path:string,data?:unknown){
 const response=await fetch('/skland/api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.value.csrf||''},body:data===undefined?undefined:JSON.stringify(data)})
 const result=await response.json()
 if(!response.ok)throw new Error(result.message||'服务暂不可用')
 return result as State
}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'请求未完成，请重试'}finally{busy.value=false}}
async function start(){await run(async()=>{try{state.value=await api('status');if(requestID&&state.value.request_id!==requestID)throw new Error('different request')}catch{if(!requestID)throw new Error('请先在 QQ 群发送 /skdlogin，再打开机器人给你的绑定链接。');state.value=await api('session',{request_id:requestID})}ready.value=true})}
async function poll(){if(!ready.value||busy.value||(state.value.complete&&!state.value.signing)||cancelled.value)return;try{state.value=await api('status')}catch(e){error.value=e instanceof Error?e.message:'会话已过期';if(timer)clearInterval(timer)}}
async function verify(){await run(async()=>{state.value=await api('credential',{token:token.value});token.value=''})}
async function commit(){await run(async()=>{state.value=await api('commit',{consent:consent.value,auto:auto.value})})}
async function sign(){await run(async()=>{state.value=await api('sign',{})})}
async function cancel(){await run(async()=>{await api('cancel',{});token.value='';cancelled.value=true;if(timer)clearInterval(timer)})}
async function copy(){try{await navigator.clipboard.writeText(state.value.command||'');copied.value=true;setTimeout(()=>copied.value=false,2000)}catch{error.value='复制未完成，请手动选中下方命令复制。'}}
onMounted(()=>{document.title='森空岛绑定 · MAA Control Center';void start();timer=setInterval(()=>void poll(),3000)})
onUnmounted(()=>{if(timer)clearInterval(timer);token.value=''})
</script>

<template>
 <div class="skland-page">
  <header class="sk-header"><a href="/" class="sk-brand">MAA<span>CONTROL CENTER</span></a><a href="/" class="sk-back"><ArrowLeft :size="14"/>管理中心</a></header>
  <main class="sk-main">
   <div class="sk-intro"><span class="sk-label">SKLAND / ACCOUNT BINDING</span><h1>每天签到，<br>从这里开始。</h1><p>连接森空岛账号，让机器人帮你完成明日方舟与终末地的每日签到。</p><div class="sk-proof"><ShieldCheck :size="19"/><span>在 QQ 群确认身份<br><strong>凭证只在本页提交</strong></span></div></div>
   <section class="sk-panel" aria-label="森空岛账号绑定">
    <ol class="sk-steps" aria-label="绑定进度"><li v-for="(name,i) in ['确认 QQ','验证凭证','完成绑定']" :key="name" :class="{active:stage>i,done:stage>i+1}"><span><Check v-if="stage>i+1" :size="12"/><template v-else>{{i+1}}</template></span>{{name}}</li></ol>
    <div v-if="cancelled" class="sk-body"><h2>已取消本次认证</h2><p>如需继续，请在 QQ 群重新发送 <code>/skdlogin</code>。</p><a href="/">返回管理中心</a></div>
    <div v-else-if="!ready" class="sk-body"><h2>{{busy?'正在检查绑定入口…':'从 QQ 群开始绑定'}}</h2><p>无需私聊机器人，也无需注册管理中心账号。</p><div v-if="error" class="sk-error" role="alert">{{error}}</div><button v-if="requestID&&!busy" class="sk-primary" @click="start">重新检查</button><div class="sk-command">/skdlogin</div></div>
    <div v-else :key="'stage-'+stage" class="sk-body" :aria-busy="busy">
     <template v-if="stage===1"><span class="sk-overline">STEP 01</span><h2>确认这是你的 QQ</h2><p>复制下方命令，发送到发起绑定的 QQ 群。只确认你自己当前网页上的命令。</p><div class="sk-command">{{state.command}}</div><button class="sk-primary" @click="copy"><Check v-if="copied" :size="17"/><Copy v-else :size="17"/>{{copied?'已复制':'复制确认命令'}}</button><div class="sk-wait"><span/>等待你在 QQ 群确认…</div><p class="sk-small">确认码 3 分钟有效。群成员打开同一链接，也无法取得你的网页会话。</p></template>
     <form v-else-if="stage===2" @submit.prevent="verify"><span class="sk-overline">STEP 02 · QQ {{state.qq}}</span><h2>验证森空岛凭证</h2><p>登录官方网页后，将凭证页面的全部 JSON 直接复制到这里，系统会自动识别可用字段。请勿发到群聊。</p><details class="sk-help"><summary>如何获取 Token？</summary><p>先登录 <a href="https://www.skland.com/" target="_blank" rel="noopener noreferrer">森空岛官网</a>，再打开 <a href="https://web-api.skland.com/account/info/hg" target="_blank" rel="noopener noreferrer">官方凭证页面</a>，全选复制页面返回的全部 JSON，不用查找或挑选 content 字段。请勿截图或转发包含凭证的页面。</p></details><label class="sk-field" for="sk-token">森空岛凭证（支持完整 JSON）</label><input id="sk-token" v-model="token" type="password" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="16384" required placeholder="粘贴完整 JSON，或直接粘贴 Token" :disabled="busy"/><button class="sk-primary" type="submit" :disabled="busy||!token.trim()">{{busy?'正在验证…':'验证凭证'}}<ArrowRight :size="17"/></button><p class="sk-small">凭证加密保存在机器人服务端，仅用于账号验证与签到。</p></form>
     <form v-else-if="stage===3" @submit.prevent="commit"><span class="sk-overline">STEP 03 · QQ {{state.qq}}</span><h2>确认绑定角色</h2><p>已验证以下角色，确认后保存绑定。</p><p v-if="state.credential_source" class="sk-small">已自动识别：{{state.credential_source}}，其他字段无需处理。</p><ul class="sk-roles"><li v-for="role in state.roles" :key="role"><Check :size="16"/>{{role}}</li></ul><label class="sk-check"><input v-model="auto" type="checkbox"/>参与每日自动签到{{state.schedule?'（北京时间 '+state.schedule.time+'）':''}}</label><label class="sk-check"><input v-model="consent" type="checkbox" required/>我同意保存凭证用于签到，了解可在 QQ 群发送 /skdlogout 删除绑定。</label><button class="sk-primary" type="submit" :disabled="busy||!consent">{{busy?'正在保存…':'确认绑定'}}<ArrowRight :size="17"/></button></form>
     <template v-else><div class="sk-success"><Check :size="25"/></div><h2>绑定完成</h2><p>QQ {{state.qq}} 已连接森空岛。你可以现在签到，或回到 QQ 群发送 <code>/skdsign</code>。</p><button class="sk-primary" :disabled="busy||state.signing" @click="sign"><RefreshCw :size="17" :class="{spinning:busy||state.signing}"/>{{busy||state.signing?'正在签到…':'立即签到'}}</button><ul v-if="state.results?.length" class="sk-results"><li v-for="(result,i) in state.results" :key="i" :class="{failed:!['success','already'].includes(result.state)}">{{result.message}}</li></ul><p class="sk-small">群内发送 /skd 查询今日状态；/skdlogout 解绑。自动通知默认关闭。</p></template>
     <p v-if="state.schedule&&!state.schedule.enabled&&stage>=3" class="sk-small">管理员尚未开启自动签到；目前可手动签到。自动签到选项将在管理员开启总开关后生效。</p><div v-if="error" class="sk-error" role="alert">{{error}}</div><button v-if="stage<4" class="sk-cancel" :disabled="busy" @click="cancel">取消本次认证</button>
    </div>
   </section>
  </main><footer class="sk-footer">MAA CONTROL CENTER<span>森空岛账号绑定 · 非官方服务</span></footer>
 </div>
</template>

<style scoped>
.skland-page{min-height:100dvh;background:#f4f4f2;color:#22251f;font-family:Inter,"Noto Sans SC","Microsoft YaHei",sans-serif}.sk-header,.sk-footer{max-width:1160px;margin:auto;display:flex;align-items:center;justify-content:space-between;padding:28px 32px}.sk-header{border-bottom:1px solid #d8d9d2}.sk-brand{display:flex;align-items:center;gap:12px;font-size:25px;font-weight:900;color:inherit;text-decoration:none;letter-spacing:-1px}.sk-brand span{font-size:10px;letter-spacing:1.2px;border-left:1px solid #b8bab1;padding-left:12px;max-width:110px}.sk-back{display:flex;align-items:center;gap:7px;font-size:12px;color:#5b6056;text-decoration:none}.sk-main{max-width:1100px;margin:0 auto;padding:90px 32px 80px;display:grid;grid-template-columns:1fr 1.15fr;gap:75px;align-items:start}.sk-label,.sk-overline{font-size:10px;font-weight:700;letter-spacing:1.6px;color:#656b5d}.sk-intro h1{font-size:clamp(34px,4.3vw,53px);line-height:1.3;letter-spacing:-2px;margin:24px 0}.sk-intro>p{font-size:14px;line-height:1.9;max-width:330px;color:#6c7166}.sk-proof{display:flex;gap:12px;margin-top:46px;line-height:1.7;font-size:12px;color:#666c5c}.sk-proof strong{font-weight:600;color:#30372a}.sk-panel{background:#fff;border:1px solid #dadcd3;box-shadow:0 12px 35px #22251f06}.sk-steps{list-style:none;display:flex;margin:0;padding:20px 24px;border-bottom:1px solid #e7e8e2;justify-content:space-between;gap:8px}.sk-steps li{display:flex;align-items:center;gap:7px;font-size:12px;color:#8b8f84}.sk-steps li>span{width:22px;height:22px;border:1px solid #d8dcd0;display:grid;place-items:center;font-size:10px}.sk-steps .active{color:#252a20}.sk-steps .active>span{background:#f4d348;border-color:#f4d348}.sk-steps .done>span{background:#e9eddf;border-color:#e9eddf}.sk-body{padding:32px;min-height:340px;animation:sk-in .2s ease-out}.sk-body h2{font-size:23px;font-weight:650;letter-spacing:-.6px;margin:14px 0}.sk-body p{font-size:14px;line-height:1.85;color:#686f60;margin:12px 0 20px}.sk-command{background:#f5f6f2;border:1px solid #dce0d4;padding:16px;margin:22px 0;font-family:monospace;font-size:14px;overflow-wrap:anywhere;user-select:all}.sk-primary{border:1px solid #e5c235;background:#f4d348;min-height:46px;padding:11px 18px;width:100%;font-size:14px;color:#272b20;font-weight:650;display:flex;align-items:center;justify-content:center;gap:9px;cursor:pointer;transition:background .15s,transform .15s}.sk-primary:hover:not(:disabled){background:#fadd67;transform:translateY(-1px)}.sk-primary:active:not(:disabled){transform:translateY(0)}.sk-primary:disabled{opacity:.55;cursor:wait}.sk-primary:focus-visible,.sk-cancel:focus-visible,input:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b49d37;outline-offset:3px}.sk-wait{display:flex;align-items:center;justify-content:center;gap:8px;font-size:12px;color:#666e5c;margin:23px 0}.sk-wait span{height:6px;width:6px;border-radius:50%;background:#bda336;animation:sk-pulse 2s infinite}.sk-body .sk-small{font-size:13px;color:#858a7d;line-height:1.8;margin:20px 0 0}.sk-cancel{border:0;background:none;color:#777f6c;font-size:12px;cursor:pointer;display:block;margin:22px auto 0;text-decoration:underline;text-underline-offset:4px}.sk-error{margin:18px 0;padding:12px;background:#fff4e9;border:1px solid #eed4bd;font-size:12px;line-height:1.7;color:#8d4e20;overflow-wrap:anywhere}.sk-help{font-size:12px;margin:20px 0;color:#626c54}.sk-help summary{cursor:pointer}.sk-help a{color:#536d29;text-decoration:underline}.sk-field{display:block;font-size:12px;font-weight:600;margin:20px 0 9px}#sk-token{width:100%;box-sizing:border-box;border:1px solid #cbd1c0;background:#fafbf8;border-radius:0;height:46px;padding:12px;font-size:14px;margin-bottom:16px}.sk-roles,.sk-results{list-style:none;padding:0;margin:20px 0}.sk-roles li{display:flex;gap:9px;align-items:center;border-bottom:1px solid #e8ebdf;padding:12px 0;font-size:13px}.sk-check{display:flex;gap:9px;align-items:start;font-size:14px;line-height:1.8;margin:16px 0;color:#68725a}.sk-check input{margin-top:5px;accent-color:#697d3f;flex-shrink:0}.sk-success{background:#edf2e4;border:1px solid #d6dfc6;color:#667e3e;display:grid;place-items:center;width:48px;height:48px;margin-bottom:20px}.sk-results li{font-size:12px;line-height:1.8;padding:8px 0;color:#557132;border-bottom:1px solid #e9ecdf}.sk-results .failed{color:#9c612e}.sk-footer{font-size:9px;letter-spacing:1.3px;color:#92978b;border-top:1px solid #d8d9d2}.sk-footer span{letter-spacing:0;font-size:11px}.spinning{animation:sk-spin 1s linear infinite}@keyframes sk-spin{to{transform:rotate(360deg)}}@keyframes sk-pulse{50%{opacity:.3}}@keyframes sk-in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(max-width:720px){.sk-header,.sk-footer{padding:22px}.sk-main{display:block;padding:35px 20px 45px}.sk-intro h1{font-size:34px;letter-spacing:-1px;margin:16px 0}.sk-intro h1 br{display:none}.sk-intro>p{max-width:none;font-size:13px}.sk-proof{margin:20px 0 28px}.sk-proof span br{display:none}.sk-proof strong{margin-left:8px}.sk-body{padding:24px;min-height:310px}.sk-steps{padding:18px}.sk-footer{gap:12px;flex-wrap:wrap}.sk-command{font-size:12px}.sk-brand{font-size:23px}.sk-back{font-size:11px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
</style>
